module.exports = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Protein Plate</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@400;600;800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#f4f6f1;--card:#fff;--ink:#16302b;--mute:#5d726c;--line:#d9e1db;--gold:#e9a500;--goldink:#3a2a00;--ok:#1f7a5a;--warn:#9a6700;\nbox-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#0f1c19;--card:#172a26;--ink:#e8f0ec;--mute:#93aaa3;--line:#27403a;--gold:#f0b429;--goldink:#2a1d00;--ok:#4cc79a;--warn:#f0b429}}\n:root[data-theme=\"dark\"]{--bg:#0f1c19;--card:#172a26;--ink:#e8f0ec;--mute:#93aaa3;--line:#27403a;--gold:#f0b429;--goldink:#2a1d00;--ok:#4cc79a;--warn:#f0b429}\n*{box-sizing:border-box}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\nbody{margin:0;background:var(--bg);color:var(--ink);font:16px/1.4 \"Bricolage Grotesque\",system-ui,sans-serif}\nmain{max-width:480px;margin:0 auto;padding:20px 16px 40px}\nh1{font-size:1rem;font-weight:600;color:var(--mute);margin:0 0 4px}\n.total{font-size:4.2rem;font-weight:800;line-height:1;letter-spacing:-.03em}\n.total small{font-size:1.2rem;font-weight:600;color:var(--mute);letter-spacing:0}\n.bar{height:14px;background:var(--line);border-radius:7px;overflow:hidden;margin:12px 0 6px}\n.bar i{display:block;height:100%;width:0;background:var(--gold);border-radius:7px;transition:width .4s}\n.bar.done i{background:var(--ok)}\n.sub{color:var(--mute);font-size:.9rem;display:flex;justify-content:space-between;align-items:center}\n.sub input{width:64px;padding:4px 6px;font-size:.9rem}\n.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px;margin-top:18px}\nlabel{display:block;font-size:.85rem;color:var(--mute);margin:10px 0 4px}\nlabel:first-child{margin-top:0}\ninput,button{font:inherit;color:var(--ink)}\ninput{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg)}\ninput:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--gold);outline-offset:1px}\n.row{display:flex;gap:10px}\n.row>*{flex:1}\n.chips{display:flex;gap:8px}\n.chips button{flex:1;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--bg);cursor:pointer}\n.chips button[aria-pressed=\"true\"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n.preview{font-size:1.5rem;font-weight:800;margin:14px 0 10px;min-height:1.9rem}\n.preview span{font-size:.9rem;font-weight:400;color:var(--mute)}\n.add{width:100%;padding:13px;border:0;border-radius:10px;background:var(--gold);color:var(--goldink);font-weight:800;cursor:pointer}\n.add:disabled{opacity:.4;cursor:default}\nul{list-style:none;margin:0;padding:0}\nli{display:flex;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)}\nli:last-child{border:0}\nli div{flex:1}\nli b{font-weight:600}\nli span{display:block;font-size:.85rem;color:var(--mute)}\nli strong{font-size:1.1rem}\nli button{border:0;background:none;color:var(--mute);font-size:1.3rem;cursor:pointer;padding:4px 8px}\n.empty{color:var(--mute);margin:0}\nh2{font-size:1rem;margin:0 0 6px}\ndetails summary{cursor:pointer;font-weight:600}\ndetails .row{margin-top:10px}\n.msg{font-size:.85rem;color:var(--mute);margin:8px 0 0}\ndetails.day{border-bottom:1px solid var(--line)}\ndetails.day:last-child{border:0}\ndetails.day>summary{display:flex;justify-content:space-between;padding:11px 0;list-style:none}\ndetails.day>summary::-webkit-details-marker{display:none}\ndetails.day>summary b.ok{color:var(--ok)}\ndetails.day ul{padding:0 0 8px 10px}\n.more{width:100%;margin-top:10px;padding:11px;border:1px solid var(--line);border-radius:10px;background:var(--bg);cursor:pointer;font-weight:600}\n.top{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:4px}\n.top h1{margin:0}\n.plus{padding:8px 14px;border:0;border-radius:999px;background:var(--gold);color:var(--goldink);font-weight:800;cursor:pointer}\ndialog{width:calc(100% - 32px);max-width:440px;border:1px solid var(--line);border-radius:14px;background:var(--card);color:var(--ink);padding:0}\ndialog::backdrop{background:rgba(0,0,0,.5)}\n.dbody{padding:18px}\n.btns{display:flex;gap:8px}\n.top{flex-wrap:wrap}\n.plus.alt{background:transparent;border:1px solid var(--line);color:var(--ink);font-weight:600}\n.tw{max-height:55vh;overflow:auto;margin-top:10px;border:1px solid var(--line);border-radius:10px}\ntable{width:100%;border-collapse:collapse;font-size:.9rem}\nth,td{padding:8px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}\nth:first-child,td:first-child{text-align:left;white-space:normal}\ntbody tr:last-child td{border:0}\nth{position:sticky;top:0;background:var(--card);color:var(--mute);font-weight:600;font-size:.8rem}\n.tag{display:inline-block;font-size:.7rem;padding:1px 6px;border-radius:8px;border:1px solid var(--line);color:var(--mute);margin-left:6px}\n.tag.c{background:var(--gold);color:var(--goldink);border-color:var(--gold)}\ntd button{border:0;background:none;cursor:pointer;font-size:1rem;padding:4px 6px}\n.sr{position:absolute;left:-9999px}\n.toprow{display:flex;justify-content:flex-end}\n.out{border:0;background:none;color:var(--mute);font-size:.85rem;cursor:pointer;padding:2px 0 6px}\n.out:hover{color:var(--ink);text-decoration:underline}\n.backup{margin-top:28px;text-align:center;color:var(--mute);font-size:.85rem}\n.backup button{border:0;background:none;color:inherit;text-decoration:underline;cursor:pointer;padding:6px 8px;font:inherit}\n.backup .msg{margin-top:4px}\n.recent{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 10px;margin-bottom:6px;cursor:grab;user-select:none;-webkit-user-select:none;touch-action:pan-x;scrollbar-width:thin;scrollbar-color:var(--line) transparent}\n.recent.drag{cursor:grabbing}\n.recent::-webkit-scrollbar{height:6px}\n.recent::-webkit-scrollbar-thumb{background:var(--line);border-radius:3px}\n.chip{flex:none;padding:8px 12px;border:1px solid var(--line);border-radius:999px;background:var(--bg);white-space:nowrap;cursor:inherit;font-size:.9rem}\n.chip:hover{border-color:var(--gold)}\n.chip b{font-weight:600}\n.backup .warn{color:var(--warn);font-weight:600}\n.week{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;height:140px;position:relative;margin-top:10px}\n.wcol{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;min-width:0}\n.wv{font-size:.75rem;color:var(--mute);height:16px;line-height:16px}\n.wbar{width:100%;max-width:38px;border-radius:6px 6px 2px 2px;background:var(--gold)}\n.wbar.ok{background:var(--ok)}\n.wbar.today{box-shadow:0 0 0 2px var(--ink)}\n.wgoal{position:absolute;left:0;right:0;border-top:2px dashed var(--mute);opacity:.7;pointer-events:none}\n.wdays{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;margin-top:6px;border-top:1px solid var(--line);padding-top:6px}\n.wd{text-align:center;font-size:.75rem;color:var(--mute);line-height:1.25}\n.wd.today{color:var(--ink);font-weight:800}\n.wsum{margin:12px 0 0;display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px 12px}\n.wleg i{display:inline-block;width:18px;border-top:2px dashed var(--mute);vertical-align:middle;margin-right:4px}\n</style>\n</head>\n<body>\n<main>\n  <div class=\"toprow\"><button type=\"button\" class=\"out\" id=\"logout\" hidden>Log out</button></div>\n  <div class=\"top\"><h1 id=\"date\"></h1><div class=\"btns\"><button type=\"button\" class=\"plus alt\" id=\"openFoods\">Foods</button><button type=\"button\" class=\"plus\" id=\"openAdd\">+ Add food</button></div></div>\n  <div class=\"total\"><span id=\"tot\">0</span><small> g protein</small></div>\n  <div class=\"bar\" id=\"bar\"><i id=\"fill\"></i></div>\n  <div class=\"sub\"><span id=\"left\"></span><span>Goal <input id=\"goal\" type=\"number\" min=\"1\" inputmode=\"numeric\" aria-label=\"Daily goal in grams\"> g</span></div>\n\n  <section class=\"card\" aria-label=\"Add food\">\n    <div id=\"recentWrap\" hidden>\n      <label id=\"recentLabel\">Frequent foods (tap one, then enter the amount)</label>\n      <div class=\"recent\" id=\"recent\" role=\"group\" aria-labelledby=\"recentLabel\"></div>\n    </div>\n    <label for=\"food\">Food</label>\n    <input id=\"food\" list=\"foods\" placeholder=\"Start typing, e.g. dhal\" autocomplete=\"off\">\n    <datalist id=\"foods\"></datalist>\n    <div id=\"stateWrap\">\n      <label>Form</label>\n      <div class=\"chips\">\n        <button type=\"button\" id=\"bRaw\" aria-pressed=\"false\">Raw</button>\n        <button type=\"button\" id=\"bCooked\" aria-pressed=\"true\">Cooked</button>\n      </div>\n    </div>\n    <label for=\"grams\" id=\"gl\">Weight (grams)</label>\n    <input id=\"grams\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"e.g. 150\">\n    <div class=\"preview\" id=\"prev\"></div>\n    <button class=\"add\" id=\"addBtn\" disabled>Add to today</button>\n  </section>\n\n  <section class=\"card\" aria-label=\"Today's meals\">\n    <h2>Today</h2>\n    <ul id=\"log\"></ul>\n    <p class=\"empty\" id=\"empty\">Nothing logged yet.</p>\n  </section>\n\n  <section class=\"card\" aria-label=\"Last 7 days\">\n    <h2>Last 7 days</h2>\n    <p class=\"empty\" id=\"weekEmpty\" hidden>No meals logged in the last 7 days.</p>\n    <div id=\"weekChart\">\n      <div class=\"week\" id=\"week\" role=\"list\" aria-label=\"Protein per day\"></div>\n      <div class=\"wdays\" id=\"wdays\" aria-hidden=\"true\"></div>\n      <p class=\"wsum\"><span id=\"wavg\"></span><span id=\"wgoalcount\"></span></p>\n      <p class=\"msg\"><span class=\"wleg\"><i></i>Goal <span id=\"wgoalval\"></span> g</span> &middot; The average counts completed days with meals (today and days with nothing logged are left out).</p>\n    </div>\n  </section>\n\n  <section class=\"card\" aria-label=\"History\">\n    <h2>History</h2>\n    <div id=\"hist\"></div>\n    <button type=\"button\" class=\"more\" id=\"hmore\" style=\"display:none\"></button>\n    <p class=\"empty\" id=\"hempty\">No earlier days yet.</p>\n  </section>\n\n  <footer class=\"backup\">\n    <button type=\"button\" id=\"bkDown\">Download backup</button> &middot;\n    <button type=\"button\" id=\"bkUp\">Restore from backup</button>\n    <input type=\"file\" id=\"bkFile\" accept=\"application/json,.json\" hidden>\n    <p class=\"msg\" id=\"bkLast\"></p>\n    <p class=\"msg\" id=\"bkMsg\" role=\"status\"></p>\n  </footer>\n</main>\n<dialog id=\"fdlg\" aria-labelledby=\"ft\" style=\"max-width:560px\">\n  <div class=\"dbody\">\n    <div class=\"top\"><h2 id=\"ft\" style=\"margin:0\">Foods</h2><button type=\"button\" class=\"more\" id=\"fclose\" style=\"width:auto;margin:0;padding:8px 14px\">Close</button></div>\n    <input id=\"fsearch\" type=\"search\" placeholder=\"Search foods\" aria-label=\"Search foods\" style=\"margin-top:12px\">\n    <div class=\"tw\"><table>\n      <thead><tr><th>Food</th><th>Raw</th><th>Cooked</th><th>Each</th><th><span class=\"sr\">Actions</span></th></tr></thead>\n      <tbody id=\"fbody\"></tbody>\n    </table></div>\n    <p class=\"msg\">Protein in grams per 100g, except \"Each\", which is per piece. Changing a food doesn't change meals you already logged.</p>\n  </div>\n</dialog>\n<dialog id=\"dlg\" aria-labelledby=\"dt\">\n  <div class=\"dbody\">\n    <h2 id=\"dt\">Add my own food</h2>\n    <label for=\"cn\">Name</label>\n    <input id=\"cn\" placeholder=\"e.g. Mum's fish curry\">\n    <div class=\"row\">\n      <div><label for=\"cr\">Protein / 100g raw</label><input id=\"cr\" type=\"number\" min=\"0\" step=\"0.1\" inputmode=\"decimal\"></div>\n      <div><label for=\"cc\">Protein / 100g cooked</label><input id=\"cc\" type=\"number\" min=\"0\" step=\"0.1\" inputmode=\"decimal\"></div>\n    </div>\n    <label for=\"cp\">Or protein per piece (for things you count, like eggs)</label>\n    <input id=\"cp\" type=\"number\" min=\"0\" step=\"0.1\" inputmode=\"decimal\">\n    <p class=\"msg\">Fill in raw/cooked, or per piece. Values for the built-in foods are estimates; check packs or a nutrition table for exact numbers.</p>\n    <p class=\"msg\" id=\"cmsg\" role=\"status\"></p>\n    <div class=\"row\" style=\"margin-top:12px\">\n      <button type=\"button\" class=\"more\" id=\"ccancel\" style=\"margin-top:0\">Cancel</button>\n      <button type=\"button\" class=\"add\" id=\"cadd\">Save food</button>\n    </div>\n  </div>\n</dialog>\n<script>\n// If the sign-in has expired, reload so the sign-in page appears\nconst _fetch=window.fetch.bind(window);\nwindow.fetch=async(...a)=>{const r=await _fetch(...a);if(r.status===401&&!String(a[0]).startsWith(\"/auth/\")){location.reload();return new Promise(()=>{})}return r};\n// [name, protein per 100g raw, protein per 100g cooked]  (approximate)\nlet FOODS={default:[],custom:[]};\nlet log={},goal=100,state=\"cooked\",editing=null;\nconst $=id=>document.getElementById(id);\nconst today=()=>{const d=new Date();return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d.getDate()).padStart(2,\"0\")};\nasync function load(){try{const [r,fr]=await Promise.all([fetch(\"/api/data\"),fetch(\"/api/foods\")]);if(!r.ok||!fr.ok)throw 0;const o=await r.json();log=o.log||{};goal=o.goal||100;FOODS=await fr.json()}catch(e){alert(\"Could not load your data. Is the server running and connected to the database?\")}}\nfunction save(){fetch(\"/api/data\",{method:\"PUT\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({log,goal})}).catch(()=>alert(\"Save failed. Is the server running?\"))}\nconst toArr=x=>[x.name,x.raw??null,x.cooked??null,x.piece??null];\nconst foods=()=>FOODS.default.concat(FOODS.custom).map(toArr);\nconst attr=t=>esc(t).replace(/\"/g,\"&quot;\");\nasync function refreshFoods(){try{const r=await fetch(\"/api/foods\");if(r.ok){FOODS=await r.json();fillList()}}catch(e){}}\n// re-reads the latest foods from the server, applies fn, validates and saves (returns an error message or null)\nasync function mutateFoods(fn){\n  try{\n    const r=await fetch(\"/api/foods\");if(!r.ok)return \"Could not read the foods file.\";\n    const F=await r.json();\n    const err=fn(F);if(err)return err;\n    const w=await fetch(\"/api/foods\",{method:\"PUT\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(F)});\n    const o=await w.json();if(!w.ok)return o.error||\"Save failed.\";\n    FOODS=o.foods;fillList();return null;\n  }catch(e){return \"Could not reach the server.\"}\n}\nconst find=n=>foods().find(f=>f[0].toLowerCase()===n.trim().toLowerCase());\nconst fmt=n=>(Math.round(n*10)/10).toString();\nfunction fillList(){$(\"foods\").innerHTML=foods().map(f=>'<option value=\"'+f[0].replace(/\"/g,\"&quot;\")+'\">').join(\"\")}\nfunction current(){\n  const f=find($(\"food\").value);if(!f)return null;\n  if(f[3]!=null)return {f,st:\"piece\",per:f[3],both:false,piece:true};\n  const opts={raw:f[1],cooked:f[2]};\n  let st=state;if(opts[st]==null)st=opts.raw!=null?\"raw\":\"cooked\";\n  return {f,st,per:opts[st],both:opts.raw!=null&&opts.cooked!=null};\n}\nconst prot=(c,g)=>c.piece?g*c.per:g*c.per/100;\nfunction updateForm(){\n  const c=current();\n  $(\"stateWrap\").style.display=c&&c.both?\"block\":\"none\";\n  if(c){$(\"bRaw\").setAttribute(\"aria-pressed\",c.st===\"raw\");$(\"bCooked\").setAttribute(\"aria-pressed\",c.st===\"cooked\")}\n  const pc=c&&c.piece;\n  $(\"gl\").textContent=pc?\"How many\":\"Weight (grams)\";\n  $(\"grams\").placeholder=pc?\"e.g. 2\":\"e.g. 150\";\n  const g=parseFloat($(\"grams\").value);\n  if(c&&g>0){$(\"prev\").innerHTML=fmt(prot(c,g))+' g <span>protein ('+(pc?c.per+' g each':c.per+' g per 100g, '+c.st)+')</span>';$(\"addBtn\").disabled=false}\n  else{$(\"prev\").textContent=c?(pc?\"Enter how many\":\"Enter the weight\"):\"\";$(\"addBtn\").disabled=true}\n}\nfunction render(){\n  const items=log[today()]||[];\n  const sum=items.reduce((a,i)=>a+i.p,0);\n  $(\"tot\").textContent=fmt(sum);\n  const pct=Math.min(100,sum/goal*100);\n  $(\"fill\").style.width=pct+\"%\";$(\"bar\").classList.toggle(\"done\",sum>=goal);\n  $(\"left\").textContent=sum>=goal?\"Goal reached\":fmt(goal-sum)+\" g to go\";\n  $(\"goal\").value=goal;\n  $(\"empty\").style.display=items.length?\"none\":\"block\";\n  $(\"log\").innerHTML=items.map((i,k)=>'<li><div><b>'+i.n.replace(/</g,\"&lt;\")+'</b><span>'+(i.s===\"piece\"?i.g+(i.g==1?\" piece\":\" pieces\"):i.g+' g, '+i.s)+'</span></div><strong>'+fmt(i.p)+' g</strong><button aria-label=\"Remove\" data-k=\"'+k+'\">&times;</button></li>').join(\"\");\n  renderHistory();\n  renderWeek();\n  renderRecent();\n  renderBackupNote();\n}\nlet histLimit=7;\nconst esc=t=>String(t).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\");\nfunction renderHistory(){\n  const days=Object.keys(log).filter(d=>d!==today()&&log[d].length).sort().reverse();\n  $(\"hempty\").style.display=days.length?\"none\":\"block\";\n  const shown=days.slice(0,histLimit);\n  $(\"hmore\").style.display=days.length>histLimit?\"block\":\"none\";\n  $(\"hmore\").textContent=\"Show older (\"+(days.length-histLimit)+\" more days)\";\n  $(\"hist\").innerHTML=shown.map(d=>{\n    const it=log[d],sum=it.reduce((a,i)=>a+i.p,0);\n    const lbl=new Date(d+\"T00:00:00\").toLocaleDateString(undefined,{weekday:\"short\",day:\"numeric\",month:\"short\",year:\"numeric\"});\n    return '<details class=\"day\"><summary><span>'+lbl+'</span><b class=\"'+(sum>=goal?\"ok\":\"\")+'\">'+fmt(sum)+' g</b></summary><ul>'+\n      it.map(i=>'<li><div><b>'+esc(i.n)+'</b><span>'+(i.s===\"piece\"?i.g+(i.g==1?\" piece\":\" pieces\"):i.g+\" g, \"+i.s)+'</span></div><strong>'+fmt(i.p)+' g</strong></li>').join(\"\")+'</ul></details>';\n  }).join(\"\");\n}\n$(\"hmore\").onclick=()=>{histLimit+=30;renderHistory()};\n$(\"date\").textContent=new Date().toLocaleDateString(undefined,{weekday:\"long\",day:\"numeric\",month:\"long\"});\n$(\"food\").addEventListener(\"input\",updateForm);\n$(\"grams\").addEventListener(\"input\",updateForm);\n$(\"bRaw\").onclick=()=>{state=\"raw\";updateForm()};\n$(\"bCooked\").onclick=()=>{state=\"cooked\";updateForm()};\n$(\"addBtn\").onclick=()=>{\n  const c=current(),g=parseFloat($(\"grams\").value);if(!c||!(g>0))return;\n  const t=today();(log[t]=log[t]||[]).push({n:c.f[0],g:g,s:c.st,p:prot(c,g)});\n  save();render();$(\"food\").value=\"\";$(\"grams\").value=\"\";updateForm();$(\"food\").focus();\n};\n$(\"log\").onclick=e=>{const k=e.target.dataset.k;if(k===undefined)return;log[today()].splice(+k,1);save();render()};\n$(\"goal\").addEventListener(\"change\",()=>{const v=parseFloat($(\"goal\").value);if(v>0){goal=v;save()}render()});\nfunction openFoodForm(ed){\n  const f=ed?FOODS[ed.group].find(x=>x.name===ed.name):null;\n  if(ed&&!f)return;\n  editing=ed;\n  $(\"dt\").textContent=f?\"Edit food\":\"Add my own food\";\n  $(\"cadd\").textContent=f?\"Save changes\":\"Save food\";\n  $(\"cn\").value=f?f.name:\"\";\n  $(\"cr\").value=f&&f.raw!=null?f.raw:\"\";\n  $(\"cc\").value=f&&f.cooked!=null?f.cooked:\"\";\n  $(\"cp\").value=f&&f.piece!=null?f.piece:\"\";\n  $(\"cmsg\").textContent=\"\";$(\"dlg\").showModal();$(\"cn\").focus();\n}\n$(\"cadd\").onclick=async()=>{\n  const n=$(\"cn\").value.trim(),r=$(\"cr\").value,c=$(\"cc\").value,pp=$(\"cp\").value;\n  if(!n||(r===\"\"&&c===\"\"&&pp===\"\")){$(\"cmsg\").textContent=\"Add a name and at least one protein value.\";return}\n  const food={name:n};\n  if(r!==\"\")food.raw=parseFloat(r);\n  if(c!==\"\")food.cooked=parseFloat(c);\n  if(pp!==\"\")food.piece=parseFloat(pp);\n  if([food.raw,food.cooked,food.piece].some(v=>v!==undefined&&!(v>=0))){$(\"cmsg\").textContent=\"Protein values must be numbers, 0 or more.\";return}\n  const ed=editing;\n  const err=await mutateFoods(F=>{\n    if(ed){const i=F[ed.group].findIndex(x=>x.name===ed.name);if(i<0)return \"That food no longer exists.\";F[ed.group][i]=food}\n    else F.custom.push(food);\n  });\n  if(err){$(\"cmsg\").textContent=err;return}\n  $(\"dlg\").close();\n  if(ed){renderFoodsTable();updateForm()}\n  else{$(\"food\").value=n;updateForm();$(\"grams\").focus()}\n};\nfunction renderFoodsTable(){\n  const q=$(\"fsearch\").value.trim().toLowerCase(),num=v=>v==null?\"–\":v,rows=[];\n  [\"custom\",\"default\"].forEach(g=>FOODS[g].forEach(f=>{if(!q||f.name.toLowerCase().includes(q))rows.push([g,f])}));\n  $(\"fbody\").innerHTML=rows.length?rows.map(([g,f])=>'<tr><td>'+esc(f.name)+'<span class=\"tag'+(g===\"custom\"?\" c\":\"\")+'\">'+g+'</span></td><td>'+num(f.raw)+'</td><td>'+num(f.cooked)+'</td><td>'+num(f.piece)+'</td><td>'+\n    '<button type=\"button\" data-a=\"edit\" data-g=\"'+g+'\" data-n=\"'+attr(f.name)+'\" aria-label=\"Edit '+attr(f.name)+'\">&#9998;</button>'+\n    '<button type=\"button\" data-a=\"del\" data-g=\"'+g+'\" data-n=\"'+attr(f.name)+'\" aria-label=\"Delete '+attr(f.name)+'\">&#10005;</button></td></tr>').join(\"\"):\n    '<tr><td colspan=\"5\" style=\"text-align:center;color:var(--mute)\">No foods match.</td></tr>';\n}\n$(\"fbody\").onclick=async e=>{\n  const b=e.target.closest(\"button\");if(!b)return;\n  const g=b.dataset.g,n=b.dataset.n;\n  if(b.dataset.a===\"edit\")openFoodForm({group:g,name:n});\n  else if(b.dataset.a===\"del\"){\n    if(!confirm('Delete \"'+n+'\"? Meals you already logged are not affected.'))return;\n    const err=await mutateFoods(F=>{const i=F[g].findIndex(x=>x.name===n);if(i>=0)F[g].splice(i,1)});\n    if(err)alert(err);\n    renderFoodsTable();updateForm();\n  }\n};\n$(\"fsearch\").addEventListener(\"input\",renderFoodsTable);\n$(\"openFoods\").onclick=async()=>{await refreshFoods();$(\"fsearch\").value=\"\";renderFoodsTable();$(\"fdlg\").showModal()};\n$(\"fclose\").onclick=()=>$(\"fdlg\").close();\n$(\"openAdd\").onclick=()=>openFoodForm(null);\n$(\"ccancel\").onclick=()=>$(\"dlg\").close();\n[\"dlg\",\"fdlg\"].forEach(id=>$(id).addEventListener(\"click\",e=>{if(e.target===$(id))$(id).close()}));\n// ----- last 7 days: bar chart, average, days the goal was reached -----\nconst dateKey=dt=>dt.getFullYear()+\"-\"+String(dt.getMonth()+1).padStart(2,\"0\")+\"-\"+String(dt.getDate()).padStart(2,\"0\");\nfunction weekDays(){\n  const out=[];\n  for(let i=6;i>=0;i--){\n    const dt=new Date();dt.setHours(12,0,0,0);dt.setDate(dt.getDate()-i); // noon avoids daylight-saving edge cases\n    const k=dateKey(dt),meals=log[k]||[];\n    out.push({k,dt,meals:meals.length,total:meals.reduce((a,m)=>a+m.p,0),today:i===0});\n  }\n  return out;\n}\nfunction renderWeek(){\n  const days=weekDays(),H=120; // the tallest bar is 120px high\n  const any=days.some(d=>d.meals>0);\n  $(\"weekEmpty\").hidden=any;$(\"weekChart\").hidden=!any;\n  if(!any)return;\n  const scale=Math.max(goal,...days.map(d=>d.total));\n  const reached=d=>d.meals>0&&d.total>=goal;\n  $(\"week\").innerHTML=days.map(d=>{\n    const px=d.meals&&d.total>0?Math.max(2,Math.round(d.total/scale*H)):0;\n    const label=d.dt.toLocaleDateString(undefined,{weekday:\"long\",day:\"numeric\",month:\"long\"})+\": \"+(d.meals?fmt(d.total)+\" g\"+(reached(d)?\", goal reached\":\"\"):\"nothing logged\");\n    return '<div class=\"wcol\" role=\"listitem\" aria-label=\"'+label+'\" title=\"'+label+'\"><span class=\"wv\">'+(d.meals?Math.floor(d.total):\"\\u2013\")+'</span><div class=\"wbar'+(reached(d)?\" ok\":\"\")+(d.today?\" today\":\"\")+'\" style=\"height:'+px+'px\"></div></div>';\n  }).join(\"\")+'<div class=\"wgoal\" style=\"bottom:'+Math.round(goal/scale*H)+'px\"></div>';\n  $(\"wdays\").innerHTML=days.map(d=>'<div class=\"wd'+(d.today?\" today\":\"\")+'\">'+(d.today?\"Today\":d.dt.toLocaleDateString(undefined,{weekday:\"short\"}))+'<br>'+d.dt.getDate()+'</div>').join(\"\");\n  const done=days.filter(d=>!d.today&&d.meals>0);\n  $(\"wavg\").innerHTML=done.length?'Average <b>'+Math.round(done.reduce((a,d)=>a+d.total,0)/done.length)+' g</b> per day':'Average: \\u2013';\n  $(\"wgoalcount\").innerHTML='Goal reached on <b>'+days.filter(reached).length+'</b> of 7 days';\n  $(\"wgoalval\").textContent=goal;\n}\n\n// ----- frequent foods: a sliding row of buttons built from your own logs -----\n// A button only picks the food (and the form you usually use). You type the amount yourself.\nlet recentList=[];\nfunction recentItems(){\n  const days=Object.keys(log).filter(d=>log[d].length).sort().reverse().slice(0,30); // last 30 days with meals\n  const map=new Map();let seen=0;\n  for(const d of days)for(const m of log[d].slice().reverse()){\n    const key=m.n.toLowerCase();\n    let e=map.get(key);if(!e){e={n:m.n,count:0,forms:new Map(),first:seen++};map.set(key,e)}\n    e.count++;\n    const f=e.forms.get(m.s);if(f)f.c++;else e.forms.set(m.s,{c:1,at:seen++});\n  }\n  const out=[];\n  for(const e of map.values()){\n    const f=find(e.n);if(!f)continue;                                   // food was deleted or renamed\n    const has={raw:f[1]!=null,cooked:f[2]!=null,piece:f[3]!=null};\n    let s=null,best=null;                                                // usual form: most common, then most recent\n    for(const [form,a] of e.forms)if(has[form]&&(!best||a.c>best.c||(a.c===best.c&&a.at<best.at))){s=form;best=a}\n    if(!s)s=f[3]!=null?\"piece\":f[2]!=null?\"cooked\":\"raw\";                // its old form is gone: use what exists\n    out.push({name:f[0],s,count:e.count,first:e.first});\n  }\n  return out.sort((a,b)=>b.count-a.count||a.first-b.first).slice(0,15);\n}\nfunction renderRecent(){\n  recentList=recentItems();\n  $(\"recentWrap\").hidden=!recentList.length;\n  $(\"recent\").innerHTML=recentList.map((it,i)=>'<button type=\"button\" class=\"chip\" data-i=\"'+i+'\">'+esc(it.name)+'</button>').join(\"\");\n}\n$(\"recent\").addEventListener(\"click\",e=>{\n  const b=e.target.closest(\".chip\");if(!b)return;\n  const it=recentList[+b.dataset.i];if(!it)return;\n  $(\"food\").value=it.name;\n  if(it.s!==\"piece\")state=it.s;\n  updateForm();$(\"grams\").focus();\n});\n// pressing Enter in the amount box adds the meal\n$(\"grams\").addEventListener(\"keydown\",e=>{if(e.key===\"Enter\"&&!$(\"addBtn\").disabled){e.preventDefault();$(\"addBtn\").click()}});\n// slide the row with the mouse: drag it, or use the mouse wheel (touch screens just swipe)\n(function(){\n  const el=$(\"recent\");let down=false,moved=false,sx=0,sl=0;\n  el.addEventListener(\"pointerdown\",e=>{if(e.pointerType!==\"mouse\"||e.button!==0)return;down=true;moved=false;sx=e.clientX;sl=el.scrollLeft});\n  window.addEventListener(\"pointermove\",e=>{\n    if(!down)return;const dx=e.clientX-sx;\n    if(Math.abs(dx)>5){moved=true;el.classList.add(\"drag\")}\n    if(moved)el.scrollLeft=sl-dx;\n  });\n  window.addEventListener(\"pointerup\",()=>{if(!down)return;down=false;el.classList.remove(\"drag\");setTimeout(()=>{moved=false},0)});\n  el.addEventListener(\"click\",e=>{if(moved){e.stopPropagation();e.preventDefault()}},true); // a drag is not a tap\n  el.addEventListener(\"wheel\",e=>{\n    if(el.scrollWidth<=el.clientWidth||Math.abs(e.deltaY)<=Math.abs(e.deltaX))return;\n    const max=el.scrollWidth-el.clientWidth;\n    if((e.deltaY<0&&el.scrollLeft<=0)||(e.deltaY>0&&el.scrollLeft>=max))return; // at the end: let the page scroll\n    e.preventDefault();el.scrollLeft+=e.deltaY;\n  },{passive:false});\n})();\n\n// ----- backup reminder (remembered per browser) -----\nconst BK_KEY=\"ppLastBackup\";\nfunction lastBackup(){try{const v=localStorage.getItem(BK_KEY);return v?new Date(v):null}catch(e){return null}}\nfunction renderBackupNote(){\n  const el=$(\"bkLast\"),d=lastBackup(),hasData=countDays(log)>0;\n  el.classList.remove(\"warn\");\n  if(!d||isNaN(d)){el.textContent=\"Last backup on this device: never\";if(hasData)el.classList.add(\"warn\");return}\n  const a=new Date();a.setHours(0,0,0,0);const b=new Date(d);b.setHours(0,0,0,0);\n  const n=Math.max(0,Math.round((a-b)/864e5));\n  el.textContent=\"Last backup on this device: \"+(n===0?\"today\":n===1?\"yesterday\":n+\" days ago\");\n  if(n>=14)el.classList.add(\"warn\");\n}\n\n// ----- backup: download everything as one file, or restore it from such a file -----\nconst J={\"Content-Type\":\"application/json\"};\nconst bkMsg=t=>{$(\"bkMsg\").textContent=t};\nconst countDays=log=>Object.values(log).filter(m=>Array.isArray(m)&&m.length).length;\nasync function buildBackup(){\n  const [fr,dr]=await Promise.all([fetch(\"/api/foods\"),fetch(\"/api/data\")]);\n  if(!fr.ok||!dr.ok)throw new Error(\"Could not read your data from the server.\");\n  const foods=await fr.json(),data=await dr.json();\n  return {app:\"protein-plate\",version:1,exportedAt:new Date().toISOString(),goal:data.goal,foods:{default:foods.default,custom:foods.custom},log:data.log};\n}\nfunction saveFile(name,obj){\n  const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:\"application/json\"}));\n  const a=document.createElement(\"a\");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();\n  setTimeout(()=>URL.revokeObjectURL(url),2000);\n}\nconst okNum=v=>typeof v===\"number\"&&isFinite(v)&&v>=0;\nconst validLog=log=>Object.entries(log).every(([d,ms])=>/^\\d{4}-\\d{2}-\\d{2}$/.test(d)&&Array.isArray(ms)&&ms.every(m=>m&&typeof m.n===\"string\"&&okNum(m.g)&&okNum(m.p)&&[\"raw\",\"cooked\",\"piece\"].includes(m.s)));\nasync function restoreFromText(text){\n  let b;\n  try{b=JSON.parse(text)}catch(e){return \"That file is not valid JSON.\"}\n  if(!b||b.app!==\"protein-plate\"||b.version!==1||!b.foods||!Array.isArray(b.foods.default)||!Array.isArray(b.foods.custom)||!b.log||typeof b.log!==\"object\"||Array.isArray(b.log)||!(b.goal>0))return \"That file is not a Protein Plate backup.\";\n  if(!validLog(b.log))return \"Restore stopped and nothing was changed: the meals in the file are not valid.\";\n  const nf=b.foods.default.length+b.foods.custom.length,nd=countDays(b.log);\n  const when=b.exportedAt&&!isNaN(new Date(b.exportedAt))?new Date(b.exportedAt).toLocaleDateString():\"an unknown date\";\n  if(!confirm(\"Restore the backup from \"+when+\" (\"+nf+\" foods, \"+nd+\" days of meals, goal \"+b.goal+\" g)?\\n\\nThis REPLACES everything currently saved.\"))return \"Restore cancelled.\";\n  // keep a safety copy of what is there now, if there is anything worth keeping\n  try{const cur=await buildBackup();if(countDays(cur.log)>0)saveFile(\"protein-plate-before-restore-\"+today()+\".json\",cur)}catch(e){}\n  const err=async r=>((await r.json().catch(()=>({}))).error||\"the file contains invalid data.\");\n  const fw=await fetch(\"/api/foods\",{method:\"PUT\",headers:J,body:JSON.stringify({default:b.foods.default,custom:b.foods.custom})});\n  if(!fw.ok)return \"Restore stopped and nothing was changed: \"+await err(fw);\n  const lw=await fetch(\"/api/data\",{method:\"PUT\",headers:J,body:JSON.stringify({log:b.log,goal:b.goal})});\n  if(!lw.ok)return \"The foods were restored, but the meals could not be saved: \"+await err(lw)+\" Try the restore again.\";\n  await load();fillList();render();updateForm();\n  return \"Restored: \"+nf+\" foods, \"+nd+\" days of meals.\";\n}\n$(\"bkDown\").onclick=async()=>{\n  bkMsg(\"\");\n  try{const b=await buildBackup();saveFile(\"protein-plate-backup-\"+today()+\".json\",b);try{localStorage.setItem(BK_KEY,new Date().toISOString())}catch(e){}renderBackupNote();bkMsg(\"Backup downloaded: \"+(b.foods.default.length+b.foods.custom.length)+\" foods, \"+countDays(b.log)+\" days of meals.\")}\n  catch(e){bkMsg(e.message)}\n};\n$(\"bkUp\").onclick=()=>$(\"bkFile\").click();\n$(\"bkFile\").onchange=async()=>{\n  const f=$(\"bkFile\").files[0];$(\"bkFile\").value=\"\";if(!f)return;\n  if(f.size>5e6){bkMsg(\"That file is too large to be a backup.\");return}\n  bkMsg(\"Restoring...\");\n  try{bkMsg(await restoreFromText(await f.text()))}catch(e){bkMsg(\"Restore failed: \"+e.message)}\n};\nif(document.querySelector('meta[name=\"pp-auth\"]'))$(\"logout\").hidden=false;\n$(\"logout\").onclick=async()=>{try{await fetch(\"/auth/logout\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:\"{}\"})}catch(e){}location.replace(\"/\")};\nload().then(()=>{fillList();render();updateForm()});\n</script>\n</body>\n</html>\n";